#!/usr/bin/env bash
# Catégories : une clé fixe (course, seminar, event) au lieu du libellé. Porte une MIGRATION.
# Prérequis : apply-docs-tutos-medias.sh.
# Usage (racine du repo) : bash apply-fix-categories.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"prisma/schema.prisma" 2>/dev/null | grep -qF "enum CategoryKey {"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "Et une grande cible ?" "apps/web/content/docs/dev/etude-de-cas/le-moteur.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-tutos-medias.sh"; exit 1; }
