restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; rmdir -p "prisma/migrations/20261212000000_category_keys" 2>/dev/null || true; rmdir -p "packages/contracts/src/categories" 2>/dev/null || true; echo "  ↩ fichiers restaurés"; }
if grep -qF "enum CategoryKey {" "prisma/schema.prisma" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
