[ "${AKFC_APPLY_ONLY:-0}" = "1" ] && { echo "Appliqué (sans vérification ni commit)."; exit 0; }
node scripts/build-procedure-map.mjs --write >/dev/null 2>&1 || { echo "❌ carte des procédures : échec"; restore; exit 1; }
echo "== prisma generate =="
if ! pnpm prisma generate > /tmp/akfc_pg.log 2>&1; then echo "❌ prisma generate ÉCHOUÉ :"; tail -8 /tmp/akfc_pg.log; restore; pnpm prisma generate >/dev/null 2>&1 || true; exit 1; fi
echo "== pnpm check =="
if pgrep -f "next dev" >/dev/null 2>&1; then
  echo "  (pnpm dev tourne : vérification sans effacer .next)"
  CHECK="node scripts/check-next-conventions.mjs && node scripts/check-tour-targets.mjs && pnpm typecheck && pnpm lint"
else
  CHECK="pnpm check"
fi
if ! bash -c "$CHECK" > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"
  grep -nE "error TS|✗ tutos|ERR_|Error:|EACCES|Permission denied" /tmp/akfc_tc.log | head -12
  echo "  … fin du journal :"; grep -v '^[[:space:]]*$' /tmp/akfc_tc.log | tail -15
  restore; pnpm prisma generate >/dev/null 2>&1 || true; exit 1
fi
echo "  ✅ check OK"
git add -- "${MODIFIED[@]}" "${CREATED[@]}" apps/web/src/features/docs/entities/procedureMap.generated.json
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
Catégories : une clé fixe (course, seminar, event), plus jamais le libellé

Les formulaires des galeries comparaient le libellé de la catégorie à
« Stage » et « Event » : une catégorie nommée « Évènement » ou « Stages »
ne proposait jamais le choix du stage ou de l'évènement, sans aucune erreur.
La vue publique des galeries rangeait de même par libellé, et la création
d'un créneau reconnaissait la catégorie des cours à son dossier.

- Category.key, enum CategoryKey (course, seminar, event), unique : c'est
  elle que lisent les galeries, la vue publique et course.create. Le libellé
  (type) reste affiché et modifiable sans rien casser
- migration 20261212000000_category_keys : attribue la clé aux catégories
  existantes par l'usage (galeries rattachées à un stage, à un évènement),
  puis par le libellé ou le dossier, et seulement s'il y a une seule
  candidate ; sinon la ligne reste « hors liste ». Aucun libellé, aucun
  dossier modifié
- formulaire : la catégorie se choisit parmi celles qui manquent, ne change
  plus ensuite (refus côté serveur) ; le libellé est proposé d'après elle.
  La liste nomme les manquantes, n'offre « Créer » que s'il en manque une,
  et signale une ligne hors liste, que son édition permet de rattacher
- category.getAll : select explicite
- tuto « Créer une catégorie » et sa fiche, remis à la liste fixe ; le
  moteur lit aussi la valeur d'un select
- schema.prisma : une ligne de doc d'AuditAction égarée sur ImageConsent,
  remise à sa place
- e2e : la catégorie des stages s'appelle « Stages d'été » dans les données
  de test ; categories.spec.ts vérifie que la galerie propose le stage
  (échoue avec l'ancienne comparaison au libellé)

